/* Support Max9295, Max96717, Max96717F */
static const struct reg_cfg ox03c_hk_ser_init[] = {
	// clang-format off
	{ 0x0002, 0x03 }, // Disable channel Z first
	{ 0x03F1, 0x09 }, // Enable PCLK output to MFP4
	{ 0x03F0, 0x51 }, // Enable pre-defined reference generation PLL(27M)
	{ 0x0570, 0x0C }, // MFP3 rise and fall slowest, MFP4 rise and fall fastest
	{ 0x0041, 0x76 }, // I2C-to-I2C master 980Kbps, 32ms' timeout
	{ 0x0006, 0xB0 }, // Enable RCLK output, enable I2C
	{ 0x0383, 0x00 }, // Pixel mode
	{ 0x0318, 0x6D }, // Route data type 0x2D(RAW14) to pipe Z
	// clang-format on
};

/* Support Max9295, Max96717, Max96717F */
static const struct reg_cfg ox03c_hk_ser_pre_stream_on_2lane[] = {
	// clang-format off
	{ 0x0330, 0x80, 5 }, // Reset MIPI RX
	{ 0x0331, 0x10, 0 }, // 2 data lanes, disable deskew, extended VC
	{ 0x0330, 0x00, 5 }, // Release MIPI RX, continuous clock, disable VC mapping, 1x4lane mode
	{ 0x0002, 0x43, 0 }, // Enable channel Z
	// clang-format on
};

/* Support Max9295, Max96717, Max96717F */
static const struct reg_cfg ox03c_hk_ser_pre_stream_on[] = {
	// clang-format off
	{ 0x0330, 0x80, 5 }, // Reset MIPI RX
	{ 0x0330, 0x00, 5 }, // Release MIPI RX, continuous clock, disable VC mapping, 1x4lane mode
	{ 0x0002, 0x43, 0 }, // Enable channel Z
	// clang-format on
};

